1	using System.Data;
2	using FluentValidation;
3	using Kanban.Business.Interfaces;
4	using Kanban.Business.Transforms;
5	using Kanban.Contracts;
6	using Kanban.DataAccess.Interfaces;
7	using Kanban.Domain.Entities;
8	using Kanban.Domain.Exceptions;
9	using Microsoft.AspNetCore.Authorization;
10	using Microsoft.Extensions.Logging;
11	using Polly;
12	using Polly.Retry;
13	
14	namespace Kanban.Business.Services;
15	
16	public sealed class LaneService : ILaneService
17	{
18	    private readonly ILaneRepository _laneRepository;
19	    private readonly IBoardRepository _boardRepository;
20	    private readonly IBoardMemberRepository _boardMemberRepository;
21	    private readonly ICurrentUserService _currentUserService;
22	    private readonly IAuthorizationService _authorizationService;
23	    private readonly IDbConnection _dbConnection;
24	    private readonly IDbConnectionFactory _transactionFactory;
25	    private readonly ILogger<LaneService> _logger;
26	
27	    private static readonly ResiliencePipeline RetryPolicy =
28	        new ResiliencePipelineBuilder()
29	            .AddRetry(new RetryStrategyOptions
30	            {
31	                MaxRetryAttempts = 5,
32	                Delay = TimeSpan.FromMilliseconds(50),
33	                BackoffType = DelayBackoffType.Exponential,
34	                UseJitter = true,
35	                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
36	                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
37	                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
38	            })
39	            .Build();
40	
41	    public LaneService(
42	        ILaneRepository laneRepository,
43	        IBoardRepository boardRepository,
44	        IBoardMemberRepository boardMemberRepository,
45	        ICurrentUserService currentUserService,
46	        IAuthorizationService authorizationService,
47	        IDbConnection dbConnection,
48	        IDbConnectionFactory transactionFactory,
49	        ILogger<LaneService> logger)
50	    {
51	        ArgumentNullException.ThrowIfNull(laneRepository);
52	        ArgumentNullException.ThrowIfNull(boardRepository);
53	        ArgumentNullException.ThrowIfNull(boardMemberRepository);
54	        ArgumentNullException.ThrowIfNull(currentUserService);
55	        ArgumentNullException.ThrowIfNull(authorizationService);
56	        ArgumentNullException.ThrowIfNull(dbConnection);
57	        ArgumentNullException.ThrowIfNull(transactionFactory);
58	        ArgumentNullException.ThrowIfNull(logger);
59	        _laneRepository = laneRepository;
60	        _boardRepository = boardRepository;
61	        _boardMemberRepository = boardMemberRepository;
62	        _currentUserService = currentUserService;
63	        _authorizationService = authorizationService;
64	        _dbConnection = dbConnection;
65	        _transactionFactory = transactionFactory;
66	        _logger = logger;
67	    }
68	
69	    public async Task<LaneDto> CreateAsync(Guid boardId, CreateLaneRequest request)
70	    {
71	        new InlineValidator<Guid>
72	            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
73	            .ValidateAndThrow(boardId);
74	        new InlineValidator<CreateLaneRequest>
75	            { v => v.RuleFor(x => x.Name).NotEmpty().MaximumLength(100) }
76	            .ValidateAndThrow(request);
77	
78	        var userId = _currentUserService.UserId!.Value;
79	        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
80	            ?? throw new NotFoundException("board.not_found", "Board not found.");
81	
82	        var auth = await _authorizationService.AuthorizeAsync(
83	            _currentUserService.Principal, new BoardContext(boardId), new BoardMembershipRequirement(BoardOperations.CreateLane));
84	        if (!auth.Succeeded)
85	            throw new ForbiddenException("lane.create_forbidden", "You do not have permission to create lanes on this board.");
86	
87	        return await RetryPolicy.ExecuteAsync(async ct =>
88	        {
89	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
