57	    .ValidateDataAnnotations()
58	    .ValidateOnStart();
59	
60	// ── Database ──────────────────────────────────────────────────────────────────
61	
62	DapperConfiguration.RegisterTypeHandlers();
63	
64	// Resolve the connection string lazily from IOptions so that WebApplicationFactory
65	// configuration overrides (applied after builder services are registered) are honoured.
66	builder.Services.AddScoped<IDbConnection>(sp =>
67	{
68	    var opts = sp.GetRequiredService<IOptions<ConnectionStringOptions>>().Value;
69	    var conn = new SqliteConnection(opts.Kanban);
70	    conn.Open();
71	    using var cmd = conn.CreateCommand();
72	    cmd.CommandText = "PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;";
73	    cmd.ExecuteNonQuery();
74	    return conn;
75	});
76	
77	// ── Exception Handling ────────────────────────────────────────────────────────
78	
79	builder.Services.AddProblemDetails(options =>
80	{
81	    options.CustomizeProblemDetails = ctx =>
82	    {
83	        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
84	        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
85	            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
86	        {
87	            ctx.ProblemDetails.Title = "You are not registered to use this application.";
88	            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
89	        }
90	    };
91	});
92	builder.Services.AddExceptionHandler<DomainExceptionHandler>();
93	builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
94	builder.Services.AddExceptionHandler<FallbackExceptionHandler>();
95	
96	// ── CORS ──────────────────────────────────────────────────────────────────────
97	
98	builder.Services.AddCors(options =>
99	    options.AddPolicy("KanbanWebApp", policy =>
100	        policy
101	            .WithOrigins(
102	                builder.Configuration
103	                    .GetSection("Cors:AllowedOrigins")
104	                    .Get<string[]>() ?? [])
105	            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
106	            .AllowAnyHeader()
107	            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));
108	
109	// ── Authentication & Authorization ───────────────────────────────────────────
110	
111	builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
112	builder.Services.AddScoped<IAuthService, AuthService>();
113	builder.Services.AddScoped<IInvitationService, InvitationService>();
114	builder.Services.AddSingleton<IDbConnectionFactory, SqliteConnectionFactory>();
115	builder.Services.AddScoped<GoogleIdentityAdapter>();
116	builder.Services.AddScoped<IUserRepository, UserRepository>();
117	builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
118	builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
119	builder.Services.AddScoped<IBoardRepository, BoardRepository>();
120	builder.Services.AddScoped<ILaneRepository, LaneRepository>();
121	builder.Services.AddScoped<ICardRepository, CardRepository>();
122	builder.Services.AddScoped<IBoardMemberRepository, BoardMemberRepository>();
123	builder.Services.AddValidatorsFromAssemblyContaining<IssueInviteRequestValidator>();
124	builder.Services.AddHttpContextAccessor();
125	builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
126	builder.Services.AddScoped<IAuthorizationHandler, BoardAuthorizationHandler>();
127	builder.Services.AddScoped<IBoardService, BoardService>();
128	builder.Services.AddScoped<ILaneService, LaneService>();
129	
130	builder.Services.AddAuthentication(options =>
131	    {
132	        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
133	        options.DefaultChallengeScheme = GoogleDefaults.AuthenticationScheme;
134	    })
135	    .AddCookie(options =>
136	    {
137	        options.LoginPath = "/api/v1/auth/signin";
138	        options.Events.OnRedirectToLogin = ctx =>
139	        {
140	            ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
141	            return Task.CompletedTask;
142	        };
143	        options.Events.OnRedirectToAccessDenied = ctx =>
144	        {
145	            ctx.Response.StatusCode = StatusCodes.Status403Forbidden;
146	            return Task.CompletedTask;
147	        };
148	    })
149	    .AddGoogle(options =>
150	    {
151	        var googleOpts = builder.Configuration
152	            .GetSection(GoogleAuthOptions.SectionName)
153	            .Get<GoogleAuthOptions>()!;
154	        options.ClientId = googleOpts.ClientId;
155	        options.ClientSecret = googleOpts.ClientSecret;
156	
157	        // ASP.NET Core's default ClaimActions remap "sub" → ClaimTypes.NameIdentifier
158	        // (a long URN). GoogleIdentityAdapter expects the raw OIDC claim names, so we
159	        // clear the defaults and map only the three fields the adapter actually reads.
160	        options.ClaimActions.Clear();
161	        options.ClaimActions.MapJsonKey("sub", "sub");
162	        options.ClaimActions.MapJsonKey("email", "email");
163	        options.ClaimActions.MapJsonKey("name", "name");
164	
165	        options.Events.OnTicketReceived = async ctx =>
166	        {
167	            var adapter = ctx.HttpContext.RequestServices
168	                .GetRequiredService<GoogleIdentityAdapter>();
169	            var authService = ctx.HttpContext.RequestServices
170	                .GetRequiredService<IAuthService>();
171	
172	            if (ctx.Principal is not null)
173	            {
174	                var identity = adapter.Extract(ctx.Principal);
175	                var claimsIdentity = ctx.Principal.Identity as System.Security.Claims.ClaimsIdentity;
176	                if (claimsIdentity is not null)
177	                {
178	                    await authService.HandleSignInAsync(
179	                        identity.Sub,
180	                        identity.Email,
181	                        claimsIdentity,
182	                        ctx.HttpContext.RequestAborted);
183	                }
184	            }
185	        };
186	    });
187	
188	builder.Services.AddAuthorizationBuilder()
189	    .AddPolicy("RegisteredUser", policy => policy
190	        .RequireAuthenticatedUser()
191	        .AddRequirements(new RegisteredUserRequirement()))
192	    .AddPolicy("Admin", policy => policy
193	        .RequireAuthenticatedUser()
194	        .RequireClaim("system_role", "admin"));
195	
196	// ── API Versioning ────────────────────────────────────────────────────────────
197	
198	builder.Services.AddApiVersioning(options =>
199	{
200	    options.DefaultApiVersion = new ApiVersion(1, 0);
201	    options.AssumeDefaultVersionWhenUnspecified = true;
202	    options.ReportApiVersions = true;
203	});
204	
205	// ── OpenAPI — development only ────────────────────────────────────────────────
206	
207	if (builder.Environment.IsDevelopment())
208	    builder.Services.AddOpenApi();
209	
210	// ── Health Checks ─────────────────────────────────────────────────────────────
211	
212	builder.Services.AddHealthChecks()
213	    .AddCheck("self", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy(), tags: ["live"])
214	    .AddCheck<DatabaseHealthCheck>("database", tags: ["ready"]);
215	
216	// ── Rate Limiting ─────────────────────────────────────────────────────────────
217	
218	builder.Services.AddRateLimiter(opts =>
219	{
220	    opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
221	    opts.OnRejected = async (ctx, _) =>
222	    {
223	        ctx.HttpContext.Response.Headers.RetryAfter = "60";
224	        await Results.Problem(
225	                title: "Too many requests",
226	                statusCode: StatusCodes.Status429TooManyRequests,
227	                detail: "Please retry after the Retry-After interval.")
228	            .ExecuteAsync(ctx.HttpContext);
229	    };
230	
231	    opts.AddPolicy("anonymous", httpContext =>
232	        RateLimitPartition.GetFixedWindowLimiter(
233	            partitionKey: httpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown",
234	            factory: _ => new System.Threading.RateLimiting.FixedWindowRateLimiterOptions
235	            {
236	                PermitLimit = 10,
237	                Window = TimeSpan.FromMinutes(1),
238	            }));
239	
240	    opts.AddSlidingWindowLimiter("authenticated", o =>
241	    {
242	        o.PermitLimit = 100;
243	        o.Window = TimeSpan.FromMinutes(1);
244	        o.SegmentsPerWindow = 6;
245	    });
246	
247	    opts.AddSlidingWindowLimiter("mutating", o =>
248	    {
249	        o.PermitLimit = 30;
250	        o.Window = TimeSpan.FromMinutes(1);
251	        o.SegmentsPerWindow = 6;
252	    });
253	});
254	
255	// ── Build ─────────────────────────────────────────────────────────────────────
256	
257	var app = builder.Build();
258	
259	// ── Migrations ────────────────────────────────────────────────────────────────
260	
261	// Read connection string post-build so WebApplicationFactory test overrides are resolved.
262	var connectionString = app.Configuration.GetConnectionString("Kanban")
263	    ?? throw new InvalidOperationException("ConnectionStrings:Kanban is required.");
