267	    .FirstOrDefault(a => a.GetName().Name == "Kanban.Data")
268	    ?? Assembly.Load("Kanban.Data");
269	
270	var upgradeResult = DeployChanges.To
271	    .SqliteDatabase(connectionString)
272	    .WithScriptsEmbeddedInAssembly(
273	        migrationsAssembly,
274	        name => name.Contains("sqlite", StringComparison.OrdinalIgnoreCase))
275	    .WithVariables(new Dictionary<string, string>
276	    {
277	        ["AdminEmail"] = seedOptions.AdminEmail,
278	        ["AdminUserId"] = Guid.NewGuid().ToString("D"),
279	        ["SeedTimestamp"] = DateTimeOffset.UtcNow.ToString("o"),
