287	
288	// ── Middleware pipeline ───────────────────────────────────────────────────────
289	// Order matters — see constitution Security Headers and Containerization sections.
290	
291	app.UseForwardedHeaders(new ForwardedHeadersOptions
292	{
293	    ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto
294	});
295	
296	if (!app.Environment.IsDevelopment())
