316	            csp.AddScriptSrc().Self();
317	            csp.AddStyleSrc().Self().UnsafeInline();
318	            csp.AddImgSrc().Self().Data().From("https://lh3.googleusercontent.com");
319	            csp.AddConnectSrc().Self();
320	            csp.AddFrameAncestors().None();
321	            csp.AddFormAction().Self().From("https://accounts.google.com");
322	        })
323	        .AddPermissionsPolicy(permissions =>
324	        {
325	            permissions.AddAccelerometer().None();
326	            permissions.AddCamera().None();
327	            permissions.AddGeolocation().None();
328	            permissions.AddMicrophone().None();
329	            permissions.AddPayment().None();
330	            permissions.AddUsb().None();
331	        }));
332	
333	app.UseExceptionHandler();
334	app.UseStatusCodePages();
335	
336	app.UseRouting();
